import{_ as p,a0 as i,w as l,s as d,ao as o,I as r,x as e,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Fedora ostree 系統上搜索軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora ostree 系統上搜索軟件包 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora ostree 系統上搜索軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora ostree 系統上搜索軟件包 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20231129 Searching for packages with ‘rpm-ostree search","title":"在 Fedora ostree 系統上搜索軟件包","tag":"202401","desc":""},"relativePath":"202401/20231129 Searching for packages with ‘rpm-ostree search.md","filePath":"[post].md"}'),h={name:"202401/20231129 Searching for packages with ‘rpm-ostree search.md"};function g(f,s,c,m,u,b){const a=i("Link");return l(),d("div",null,[s[24]||(s[24]=o(`<h1 id="在-fedora-ostree-系統上搜索軟件包" tabindex="-1">在 Fedora ostree 系統上搜索軟件包 <a class="header-anchor" href="#在-fedora-ostree-系統上搜索軟件包" aria-label="Permalink to “在 Fedora ostree 系統上搜索軟件包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/01/152807zv5flffxfs7xjurs.jpg" alt=""></p><blockquote><p>本文介紹如何使用 rpm-ostree 查找要添加到基於 ostree 的系統（例如 Silverblue 和 Kinoite）的應用。</p></blockquote><p>基於 Fedora ostree 的系統的主要優點之一是系統的不可變性。該鏡像不僅是隻讀的，而且是預先構建在 Fedora 服務器上的。因此，更新正在運行的系統會下載更新增量（即僅差異）並修補系統。這使得許多安裝在默認情況下都是相同的。</p><p>對於大多數人來説，預構建的鏡像就足夠了，因為通常鼓勵用户同時使用 Flatpak 安裝應用，使用工具箱進行開發任務。但是，如果特定應用不符合此要求並且用户需要在主機系統上安裝應用怎麼辦？</p><p>在這種情況下，可以選擇在系統上覆蓋軟件包，在本地創建一個新的鏡像，在標準鏡像上添加軟件包。</p><p>但是，我如何知道我要安裝哪個包？搜索功能怎麼樣？</p><h3 id="老方法-toolbox-dnf-search" tabindex="-1">老方法（toolbox + dnf search） <a class="header-anchor" href="#老方法-toolbox-dnf-search" aria-label="Permalink to “老方法（toolbox + dnf search）”">​</a></h3><p>雖然始終可以通過支持 PackageKit 的軟件中心（例如 GNOME “<ruby>軟件<rt>Software</rt></ruby>” 應用 或 KDE “<ruby>發現<rt>Discover</rt></ruby>” 應用）搜索軟件包，但通過 CLI 來搜索軟件包有點困難。</p><p>由於 <code>rpm-ostree</code> 不曾提供搜索命令，因此常見的搜索方式是使用 <code>toolbox enter</code> 進入工具箱並使用 <code>dnf search &lt;搜索詞&gt;</code> 進行搜索。這樣做的缺點是需要在工具箱中啓用相同的倉庫才能獲得正確的搜索結果。</p><p>搜索 <code>neofetch</code> 的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ toolbox enter</span></span>
<span class="line"><span>&lt;Note that at this point the toolbox command might request creating a toolbox, which might involve downloading a container image&gt;</span></span>
<span class="line"><span>⬢[fedora@toolbox ~]$ dnf search neofetch</span></span>
<span class="line"><span>&lt;snip&gt; </span></span>
<span class="line"><span>=== Name Exactly Matched: neofetch ===</span></span>
<span class="line"><span>neofetch.noarch : CLI system information tool written in Bash</span></span>
<span class="line"><span>=== Summary Matched: neofetch ===</span></span>
<span class="line"><span>fastfetch.x86_64 : Like neofetch, but much faster because written in c</span></span></code></pre></div><h3 id="新方法-rpm-ostree-search" tabindex="-1">新方法（rpm-ostree search） <a class="header-anchor" href="#新方法-rpm-ostree-search" aria-label="Permalink to “新方法（rpm-ostree search）”">​</a></h3>`,13)),r("p",null,[s[1]||(s[1]=e("從 ",-1)),t(a,{href:"https://github.com/coreos/rpm-ostree/releases/tag/v2023.6"},{default:n(()=>[...s[0]||(s[0]=[e("version 2023.6",-1)])]),_:1}),s[2]||(s[2]=e(" 開始，",-1)),s[3]||(s[3]=r("code",null,"rpm-ostree",-1)),s[4]||(s[4]=e(" 支持 ",-1)),s[5]||(s[5]=r("code",null,"search",-1)),s[6]||(s[6]=e(" 命令，允許用户使用 ",-1)),s[7]||(s[7]=r("code",null,"rpm-ostree",-1)),s[8]||(s[8]=e(" 搜索可用的軟件包。一個示例命令是：",-1))]),s[25]||(s[25]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm-ostree search *kernel</span></span></code></pre></div><p>要使用搜索命令，請首先確保你使用的是 <code>rpm-ostree</code> 2023.6 或更高版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree --version</span></span>
<span class="line"><span>rpm-ostree:</span></span>
<span class="line"><span>    Version: &#39;2023.8&#39;</span></span>
<span class="line"><span>    Git: 9a99d0af32640b234318815a256a2d11e35fa64c</span></span>
<span class="line"><span>    Features:</span></span>
<span class="line"><span>    - rust</span></span>
<span class="line"><span>    - compose</span></span>
<span class="line"><span>    - container</span></span>
<span class="line"><span>    - fedora-integration</span></span></code></pre></div><p>如果滿足版本要求，你應該能夠運行 <code>rpm-ostree search &lt;搜索詞&gt;</code>。</p><p>這是一個使用 <code>rpm-ostree search</code> 搜索 <code>neofetch</code> 的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree search neofetch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>===== Name Matched =====</span></span>
<span class="line"><span>neofetch : CLI system information tool written in Bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>===== Summary Matched =====</span></span>
<span class="line"><span>fastfetch : Like neofetch, but much faster because written in c</span></span></code></pre></div><p><em>（題圖：DA/5d27838e-6068-46a6-9bca-4ec486d65c46）</em></p><hr>`,8)),r("p",null,[s[10]||(s[10]=e("via: ",-1)),t(a,{href:"https://fedoramagazine.org/searching-for-packages-with-rpm-ostree-search/"},{default:n(()=>[...s[9]||(s[9]=[e("https://fedoramagazine.org/searching-for-packages-with-rpm-ostree-search/",-1)])]),_:1})]),r("p",null,[s[15]||(s[15]=e("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/mateusrodcosta/"},{default:n(()=>[...s[11]||(s[11]=[e("Mateus Rodrigues Costa",-1)])]),_:1}),s[16]||(s[16]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[12]||(s[12]=[e("lujun9972",-1)])]),_:1}),s[17]||(s[17]=e(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[13]||(s[13]=[e("geekpi",-1)])]),_:1}),s[18]||(s[18]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[e("wxy",-1)])]),_:1})]),r("p",null,[s[21]||(s[21]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[19]||(s[19]=[e("LCTT",-1)])]),_:1}),s[22]||(s[22]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...s[20]||(s[20]=[e("Linux中國",-1)])]),_:1}),s[23]||(s[23]=e(" 榮譽推出",-1))])])}const T=p(h,[["render",g]]);export{C as __pageData,T as default};
